import os
from argparse import ArgumentParser
from ta5g_scfc.replicator import ScfcReplicator


class CliParser(object):
    """ Class that provides command line interface and parses provided arguments. """

    def parse_arguments(self):
        """ Method that parses CLI arguments. """
        parser = ArgumentParser(
            description="Command line interface for copying parameters from one SCFC file to another."
        )
        self._add_arguments(parser)
        args = parser.parse_args()
        args.func(args)

    def _add_arguments(self, parser):
        parser.add_argument(
            '-s', '--source-scfc', help="Path of source scfc file", metavar='SOURCE_FILE', type=file, required=True
        )
        parser.add_argument(
            '-b', '--base-scfc', help="Path of base scfc file", metavar='BASE_FILE', type=file, required=True
        )
        parser.add_argument(
            '-c',
            '--config',
            help="Path of file containing scfc parameter names",
            type=file,
            metavar='CONFIG_FILE',
            required=True,
        )
        parser.add_argument(
            '-o', '--output-scfc', help="Path of output scfc file", metavar='OUTPUT_FILE', default="output.xml"
        )
        parser.set_defaults(func=self._run_replicate_scfc)

    def _run_replicate_scfc(self, args):
        """ Method that runs configuration for starting a configured egate. """
        replicator = ScfcReplicator(
            source_file_path=os.path.abspath(args.source_scfc.name),
            base_file_path=os.path.abspath(args.base_scfc.name),
            config_file=args.config,
            target_file_path=args.output_scfc,
        )
        replicator.replicate()
